Console.WriteLine("===== Student Results System =====");
bool continueProgram = true;

while (continueProgram)
{
    Console.Write("Enter student name: ");
    string name = Console.ReadLine() ?? "";

    int total = 0;
    bool validInput = true;

    for (int i = 1; i <= 3; i++)
    {
        Console.Write($"Enter mark {i}: ");
        if (int.TryParse(Console.ReadLine() ?? "0", out int mark))
        {
            if (mark >= 0 && mark <= 100)
            {
                total += mark;
            }
            else
            {
                Console.WriteLine("Mark must be between 0 and 100.");
                validInput = false;
                break;
            }
        }
        else
        {
            Console.WriteLine("Please enter a valid number.");
            validInput = false;
            break;
        }
    }

    if (validInput)
    {
        int average = total / 3;
        string grade = average >= 90 ? "A" : average >= 80 ? "B" : average >= 70 ? "C" : average >= 60 ? "D" : "F";
        bool passed = average >= 50;

        Console.WriteLine();
        Console.WriteLine($"Name: {name}");
        Console.WriteLine($"Average: {average}");
        Console.WriteLine($"Grade: {grade}");
        Console.WriteLine(passed ? "Status: PASS" : "Status: FAIL");
        Console.WriteLine();
    }

    Console.Write("Enter another student? (yes/no): ");
    string response = Console.ReadLine()?.ToLower() ?? "";
    continueProgram = response == "yes" || response == "y";
}
